`timescale 1ns / 1ps
// System test of jrp_rt_core (jrp_top + jrp_rt_ingest): one golden case is streamed NREP times back to back into
// the AXI-Stream port (as AXI-DMA would, optionally paced), and every window must give the golden counters and
// histograms. The frame start is generated by the sequencer; the host only configures, enables and acknowledges.
// Plusargs as tb_board_core (PFX CNT N NS MX MY TX TY E2X E2Y HAS_Y) plus NREP, PERIOD, PV (% offered), DROP.
module tb_rt_core;
    parameter integer MAX_M = 6;
    parameter integer HIST_K = 8192;
    parameter integer K = 2;
    parameter integer DEPTH = 8192;
    localparam [19:0] CTRL = 20'h00000, RQA = 20'h20000, PERF = 20'h40000, RT = 20'h60000;

    reg clk = 0, rst_n = 0;
    always #5 clk = ~clk;

    reg [19:0] awaddr, araddr; reg awvalid, wvalid, bready, arvalid, rready; reg [31:0] wdata;
    wire awready, wready, bvalid, arready, rvalid; wire [31:0] rdata; wire [1:0] bresp, rresp;
    reg [63:0] s_tdata; reg s_tvalid; wire s_tready; wire irq;
    jrp_rt_core #(.MAX_M(MAX_M), .K(K), .RING_DEPTH(DEPTH)) dut (
        .clk(clk), .rst_n(rst_n),
        .s_axi_awaddr(awaddr), .s_axi_awvalid(awvalid), .s_axi_awready(awready),
        .s_axi_wdata(wdata), .s_axi_wstrb(4'hF), .s_axi_wvalid(wvalid), .s_axi_wready(wready),
        .s_axi_bresp(bresp), .s_axi_bvalid(bvalid), .s_axi_bready(bready),
        .s_axi_araddr(araddr), .s_axi_arvalid(arvalid), .s_axi_arready(arready),
        .s_axi_rdata(rdata), .s_axi_rresp(rresp), .s_axi_rvalid(rvalid), .s_axi_rready(rready),
        .s_axis_samples_tdata(s_tdata), .s_axis_samples_tvalid(s_tvalid), .s_axis_samples_tready(s_tready),
        .s_axis_samples_tlast(1'b0), .irq(irq));

    task wr(input [19:0] a, input [31:0] d);
        begin
            @(posedge clk); #1; awaddr = a; wdata = d; awvalid = 1; wvalid = 1;
            @(posedge clk); while (!(awready && wready)) @(posedge clk);
            #1; awvalid = 0; wvalid = 0;
            while (!bvalid) @(posedge clk);
            @(posedge clk); #1;
        end
    endtask
    task rd(input [19:0] a, output [31:0] d);
        begin
            @(posedge clk); #1; araddr = a; arvalid = 1;
            @(posedge clk); while (!arready) @(posedge clk);
            #1; arvalid = 0;
            while (!rvalid) @(posedge clk);
            d = rdata; @(posedge clk); #1;
        end
    endtask

    string pfx, cnt_file;
    integer n, ns, mx, my, tx, ty, has_y, NREP, PERIOD, PV, DROP;
    reg [31:0] e2x, e2y;
    reg [31:0] sx [0:(1<<16)-1];
    reg [31:0] sy [0:(1<<16)-1];
    reg [31:0] cw [0:(1<<16)-1];
    reg [31:0] exp_det [0:HIST_K-1];
    reg [31:0] exp_lam [0:HIST_K-1];
    integer i, errors = 0, frames = 0, top, tmo, sent = 0, total;
    reg [31:0] got, nx, ny, base_x, base_y, tr_lo, tr_hi, tw_lo, tw_hi;

    // ---- stream source: the case repeated NREP times ----
    initial begin
        s_tvalid = 0; s_tdata = 0;
        wait (rst_n);
        repeat (40) @(posedge clk);
        wait (total > 0);
        @(posedge clk); #1;
        while (sent < total) begin
            if (($urandom % 100) < PV) begin
                s_tdata = {has_y ? sy[sent % ns] : 32'd0, sx[sent % ns]}; s_tvalid = 1;
                @(posedge clk); while (!s_tready) @(posedge clk);
                sent = sent + 1; #1;
            end else begin s_tvalid = 0; @(posedge clk); #1; end
        end
        s_tvalid = 0;
    end

    task check_frame;
        integer e;
        begin
            e = 0;
            rd(RQA + 20'h008, got); if (got !== cw[0]) begin e = e + 1; $display("  rr_count got %0d want %0d", got, cw[0]); end
            rd(RQA + 20'h010, got); if (got !== cw[1]) begin e = e + 1; $display("  det_points got %0d want %0d", got, cw[1]); end
            rd(RQA + 20'h018, got); if (got !== cw[2]) begin e = e + 1; $display("  det_lines got %0d want %0d", got, cw[2]); end
            rd(RQA + 20'h01C, got); if (got !== cw[3]) begin e = e + 1; $display("  l_max got %0d want %0d", got, cw[3]); end
            rd(RQA + 20'h020, got); if (got !== cw[4]) begin e = e + 1; $display("  lam_points got %0d want %0d", got, cw[4]); end
            rd(RQA + 20'h028, got); if (got !== cw[5]) begin e = e + 1; $display("  lam_lines got %0d want %0d", got, cw[5]); end
            rd(RQA + 20'h02C, got); if (got !== cw[6]) begin e = e + 1; $display("  v_max got %0d want %0d", got, cw[6]); end
            top = (cw[3] > cw[6] ? cw[3] : cw[6]) + 1; if (top > HIST_K - 1) top = HIST_K - 1;
            for (i = 0; i <= top; i = i + 1) begin
                rd(RQA + 20'h01000 + 4*i, got);
                if (got !== exp_det[i]) begin e = e + 1; if (e < 8) $display("  DET bin %0d got %0d want %0d", i, got, exp_det[i]); end
                rd(RQA + 20'h01000 + 4*HIST_K + 4*i, got);
                if (got !== exp_lam[i]) begin e = e + 1; if (e < 8) $display("  LAM bin %0d got %0d want %0d", i, got, exp_lam[i]); end
            end
            $display("%s window %0d", (e == 0) ? "PASS" : "FAIL", frames);
            errors = errors + e;
        end
    endtask

    initial begin
        if (!$value$plusargs("PFX=%s", pfx)) begin $display("FAIL: +PFX missing"); $finish; end
        if (!$value$plusargs("CNT=%s", cnt_file)) begin $display("FAIL: +CNT missing"); $finish; end
        if (!$value$plusargs("N=%d", n)) n = 0;
        if (!$value$plusargs("NS=%d", ns)) ns = 0;
        if (!$value$plusargs("MX=%d", mx)) mx = 1;
        if (!$value$plusargs("MY=%d", my)) my = 1;
        if (!$value$plusargs("TX=%d", tx)) tx = 1;
        if (!$value$plusargs("TY=%d", ty)) ty = 1;
        if (!$value$plusargs("E2X=%h", e2x)) e2x = 32'hFFFFFFFF;
        if (!$value$plusargs("E2Y=%h", e2y)) e2y = 32'hFFFFFFFF;
        if (!$value$plusargs("HAS_Y=%d", has_y)) has_y = 1;
        if (!$value$plusargs("NREP=%d", NREP)) NREP = 3;
        if (!$value$plusargs("PERIOD=%d", PERIOD)) PERIOD = 0;
        if (!$value$plusargs("PV=%d", PV)) PV = 100;
        if (!$value$plusargs("DROP=%d", DROP)) DROP = 0;
        $readmemh({pfx, "_x.hex"}, sx);
        if (has_y) $readmemh({pfx, "_y.hex"}, sy);
        $readmemh(cnt_file, cw);
        for (i = 0; i < HIST_K; i = i + 1) begin exp_det[i] = 0; exp_lam[i] = 0; end
        for (i = 0; i < cw[7]; i = i + 1) exp_det[cw[9 + 2*i]] = cw[10 + 2*i];
        for (i = 0; i < cw[8]; i = i + 1) exp_lam[cw[9 + 2*cw[7] + 2*i]] = cw[10 + 2*cw[7] + 2*i];
        if (!has_y) begin my = 1; ty = 1; e2y = 32'hFFFFFFFF; end
        nx = ns - (mx-1)*tx; ny = ns - (my-1)*ty; base_x = nx - n; base_y = ny - n;
        total = 0;
        awvalid = 0; wvalid = 0; bready = 1; arvalid = 0; rready = 1; awaddr = 0; araddr = 0; wdata = 0;
        repeat (5) begin @(posedge clk); #1; end
        rst_n = 1;
        repeat (3) begin @(posedge clk); #1; end

        wr(CTRL + 20'h008, ns);  wr(CTRL + 20'h00C, mx);  wr(CTRL + 20'h010, tx);  wr(CTRL + 20'h014, e2x);
        wr(CTRL + 20'h024, my);  wr(CTRL + 20'h028, ty);  wr(CTRL + 20'h02C, e2y);
        wr(CTRL + 20'h018, 2);   wr(CTRL + 20'h01C, 2);
        wr(CTRL + 20'h034, base_x); wr(CTRL + 20'h038, base_y); wr(CTRL + 20'h03C, n);
        wr(RT + 20'h0C, PERIOD);
        wr(RT + 20'h00, 32'h1 | (DROP ? 32'h8 : 32'h0));      // enable
        total = NREP * ns;                                       // releases the source

        tmo = 0;
        while (frames < NREP && tmo < 60000000) begin
            @(posedge clk); tmo = tmo + 1;
            if (irq) begin
                frames = frames + 1;
                check_frame;
                wr(RT + 20'h00, 32'h4 | 32'h1 | (DROP ? 32'h8 : 32'h0));    // ACK
            end
        end
        if (frames < NREP) begin errors = errors + 1; $display("TIMEOUT after %0d windows", frames); end
        repeat (200) @(posedge clk);
        rd(RT + 20'h1C, got); if (got !== NREP) begin errors = errors + 1; $display("FRAMES_DONE %0d want %0d", got, NREP); end
        rd(RT + 20'h18, got); $display("  dropped %0d", got);
        if (!DROP && got !== 0) begin errors = errors + 1; end
        rd(RT + 20'h14, got); $display("  OCC_MAX %0d", got);
        rd(RT + 20'h20, tr_lo); rd(RT + 20'h24, tr_hi); rd(RT + 20'h28, tw_lo); rd(RT + 20'h2C, tw_hi);
        $display("  last window: ready at cycle %0d, result at cycle %0d, latency %0d cycles", tr_lo, tw_lo, tw_lo - tr_lo);
        $display("%s: %0d windows, %0d errors", (errors == 0) ? "ALLPASS" : "SOMEFAIL", frames, errors);
        $finish;
    end
endmodule
